package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.TimeZone;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for DurationFormatUtils.formatPeriod to maximize branch and line coverage.
 */
public class DurationFormatUtils_formatPeriod_TriageGen1Test {

    private static final TimeZone GMT = TimeZone.getTimeZone("GMT");
    private static final TimeZone EST = TimeZone.getTimeZone("EST");

    @Test
    public void testFormatPeriod_ShortDuration_UsesFormatDuration() {
        // Less than 28 days: should trigger the first if block
        long start = 1000L;
        long end = 2000L; // 1 second diff
        String result = DurationFormatUtils.formatPeriod(start, end, "s's'", false, GMT);
        assertEquals("1s", result);
    }

















    /**
     * Helper class to simulate Calendar functionality for testing
     */
    private static class CalendarUtils {
        static long getMillis(int year, int month, int day, int hour, int min, int sec) {
            java.util.Calendar cal = java.util.Calendar.getInstance(TimeZone.getTimeZone("GMT"));
            cal.clear();
            cal.set(Calendar.YEAR, year);
            cal.set(Calendar.MONTH, month);
            cal.set(Calendar.DATE, day);
            cal.set(Calendar.HOUR_OF_DAY, hour);
            cal.set(Calendar.MINUTE, min);
            cal.set(Calendar.SECOND, sec);
            cal.set(Calendar.MILLISECOND, 0);
            return cal.getTimeInMillis();
        }
    }
}

